FUNCTION_BLOCK FB_P11
VAR_INPUT
    Mode : BOOL;
    ForwardButton : BOOL;
    ReverseButton : BOOL;
    SensorA : BOOL;
    SensorB : BOOL;
    SensorC : BOOL;
    ButtonA : BOOL;
    ButtonB : BOOL;
    ButtonC : BOOL;
END_VAR
VAR_OUTPUT
    MotorForward : BOOL := FALSE;
    MotorReverse : BOOL := FALSE;
    CompletionLight : BOOL := FALSE;
END_VAR
VAR
    (* 0 = IDLE/current station A; 1 = moving to B;
       2 = waiting at B; 3 = moving to C;
       4 = waiting at C; 5 = completed. *)
    StationState : INT := 0;
    StartupScans : USINT := 0;
    PreviousMode : BOOL := FALSE;
    PreviousButtonA : BOOL := FALSE;
    PreviousButtonB : BOOL := FALSE;
    PreviousButtonC : BOOL := FALSE;
    RiseA : BOOL;
    RiseB : BOOL;
    RiseC : BOOL;
END_VAR

(*
需求原文：
A simple automated production line consists of three workstations: Workstation A, Workstation B, and Workstation C. The product needs to go through these three stations in sequence to be considered fully completed. There is a motor in the production line that is responsible for moving the product from one workstation to the next. The sequence of the line is from Workstation A to Workstation B, and then to Workstation C. Each workstation has a sensor (used to detect if the product has arrived) and a button (used to trigger the signal that the station's processing is complete).
Control requirements:
1. Mode Switching: The mode switch (Mode) is used to switch between manual and automatic modes of the production line.
2. Manual Mode: In manual mode, the forward rotation button (ForwardButton) controls the forward rotation of the motor, and the reverse rotation button (ReverseButton) controls the reverse rotation of the motor. Forward and reverse rotation operations need to be interlocked and cannot be performed simultaneously.
3. Automatic Mode:
   - When the product arrives at Workstation A, SensorA detects the product, and after the operator triggers the processing complete signal via ButtonA, the motor starts forward rotation to move the product to Workstation B.
   - When the product arrives at Workstation B, SensorB detects the product, the motor stops, and after the operator triggers the processing complete signal via ButtonB, the motor starts forward rotation to move the product to Workstation C.
   - When the product arrives at Workstation C, SensorC detects the product, the motor stops, and after the operator triggers the processing complete signal via ButtonC, the completion indicator light (CompletionLight) turns on, indicating that the product processing is complete. When the product is taken away, i.e., SensorC no longer detects the product, the completion indicator light (CompletionLight) turns off.

Scan period: 20 ms.
C10 G[0,1] is implemented as two initial inhibited scans.
Completion buttons use rising edges, tracked in every mode.
Leaving automatic mode discards unfinished automatic progression;
a completed product retains its light until SensorC becomes FALSE.

Specification limitation retained for review:
The formal note refers to emergency-stop abnormal tests, but no emergency-stop
input or observable emergency-stop condition exists in this interface.
Emergency-stop behavior cannot be implemented or adjudicated from these inputs.
No compilation or cycle-test verification is claimed.
*)

RiseA := ButtonA AND NOT PreviousButtonA;
RiseB := ButtonB AND NOT PreviousButtonB;
RiseC := ButtonC AND NOT PreviousButtonC;

MotorForward := FALSE;
MotorReverse := FALSE;

IF NOT SensorC THEN
    CompletionLight := FALSE;
END_IF;

IF StartupScans < 2 THEN
    StartupScans := StartupScans + 1;
    StationState := 0;
    CompletionLight := FALSE;
ELSE
    IF NOT Mode THEN
        StationState := 0;
        (* Conflicting manual commands stop both directions. *)
        MotorForward := ForwardButton AND NOT ReverseButton;
        MotorReverse := ReverseButton AND NOT ForwardButton;
    ELSE
        IF NOT PreviousMode THEN
            StationState := 0;
        END_IF;

        IF CompletionLight THEN
            (* Hold independently of mode until the product leaves C. *)
            StationState := 5;
        ELSE
            CASE StationState OF
                0:
                    IF SensorA AND RiseA THEN
                        StationState := 1;
                        MotorForward := TRUE;
                    END_IF;

                1:
                    IF SensorB THEN
                        (* Arrival always stops transport for this scan.
                           A coincident completion edge is retained by
                           advancing the state for the next scan. *)
                        IF RiseB THEN
                            StationState := 3;
                        ELSE
                            StationState := 2;
                        END_IF;
                    ELSE
                        MotorForward := TRUE;
                    END_IF;

                2:
                    IF SensorB AND RiseB THEN
                        StationState := 3;
                        MotorForward := TRUE;
                    END_IF;

                3:
                    IF SensorC THEN
                        IF RiseC THEN
                            CompletionLight := TRUE;
                            StationState := 5;
                        ELSE
                            StationState := 4;
                        END_IF;
                    ELSE
                        MotorForward := TRUE;
                    END_IF;

                4:
                    IF SensorC AND RiseC THEN
                        CompletionLight := TRUE;
                        StationState := 5;
                    END_IF;

                5:
                    (* CompletionLight is already cleared on removal. *)
                    StationState := 0;

                ELSE
                    (* Invalid internal state: stop and reinitialize. *)
                    StationState := 0;
            END_CASE;
        END_IF;
    END_IF;
END_IF;

PreviousButtonA := ButtonA;
PreviousButtonB := ButtonB;
PreviousButtonC := ButtonC;
PreviousMode := Mode;

END_FUNCTION_BLOCK
